58	    /**
59	     * Derives the owner's locality (region) from the region-and-hash identity: the {@code <REGION>}
60	     * segment of the {@code <REGION>-<HASH8>} {@code customerCode}. The region embedded in the code
61	     * is itself derived (postcode preferred, then city) when the owner is created, so a postcode in a
62	     * known range still wins over the city. When no such code is present (e.g. legacy owners), falls
63	     * back to deriving the region live from the postcode/city via {@link OwnerRegion}.
64	     */
65	    default String deriveLocality(Owner owner) {
66	        String code = owner.getCustomerCode();
67	        if (code != null) {
68	            int dash = code.indexOf('-');
69	            if (dash > 0) {
70	                return code.substring(0, dash);
71	            }
72	        }
73	        return OwnerRegion.fromPostcodeOrCity(owner.getPostcode(), owner.getCity());
74	    }
75	
76	    /**
77	     * Computes the single Luhn check digit (0-9) over the digits contained in the given
78	     * customerCode. Non-digit characters (the separators) are ignored; from the rightmost digit
79	     * leftwards every second digit is doubled (subtracting 9 when the result exceeds 9), and the
80	     * check digit is {@code (10 - (sum % 10)) % 10}. Returns 0 when the code is null.
81	     */
82	    default int luhnCheckDigit(String customerCode) {
83	        if (customerCode == null) {
84	            return 0;
85	        }
86	        int sum = 0;
87	        boolean dbl = true;
88	        for (int i = customerCode.length() - 1; i >= 0; i--) {
89	            char c = customerCode.charAt(i);
90	            if (c < '0' || c > '9') {
91	                continue;
92	            }
93	            int d = c - '0';
94	            if (dbl) {
95	                d *= 2;
96	                if (d > 9) {
97	                    d -= 9;
98	                }
99	            }
100	            sum += d;
101	            dbl = !dbl;
102	        }
103	        return (10 - (sum % 10)) % 10;
104	    }
105	
106	    /**
107	     * Composes the owner's salutation: the honorific {@code title} followed by a single space and
108	     * the {@code lastName} when a title is supplied, or just the {@code lastName} when no title is
109	     * given (null or blank).
110	     */
111	    default String composeSalutation(Owner owner) {
112	        String title = owner.getTitle();
113	        if (title == null || title.isBlank()) {
114	            return owner.getLastName();
115	        }
116	        return title + " " + owner.getLastName();
117	    }
